def get_effective_settings_proper(service_name):
    svc_path = os.path.join(services_dir, service_name)

    # Find config file
    config_file = None
    for ext in ['config.json', 'config.yaml', 'config.toml', 'config.ini', 'service.env']:
        candidate = os.path.join(svc_path, ext)
        if os.path.exists(candidate):
            config_file = candidate
            break

    settings = {}

    def extract_from_dict(data, prefix=''):
        """Recursively flatten dict with uppercase keys and dot notation, 
        but also special-case known nested structures."""
        if isinstance(data, dict):
            for k, v in data.items():
                key = (prefix + '_' + k if prefix else k).upper()
                if isinstance(v, dict):
                    extract_from_dict(v, prefix + '_' + k if prefix else k)
                elif isinstance(v, bool):
                    settings[key] = 'true' if v else 'false'
                else:
                    settings[key] = str(v)

    if config_file:
        if config_file.endswith('.json'):
            with open(config_file, 'r') as f:
                data = json.load(f)
                extract_from_dict(data)
        elif config_file.endswith('.yaml') or config_file.endswith('.yml'):
            with open(config_file, 'r') as f:
                data = yaml.safe_load(f)
                extract_from_dict(data)
        elif config_file.endswith('.toml'):
            with open(config_file, 'rb') as f:
                data = tomli.load(f)
                extract_from_dict(data)
        elif config_file.endswith('.ini'):
            cp = configparser.ConfigParser()
            cp.read(config_file)
            for section in cp.sections():
                for key in cp[section]:
                    settings[f"{section.upper()}_{key.upper()}"] = cp[section][key]
        elif config_file.endswith('.env'):
            env_settings = parse_env_file(config_file)
            settings.update(env_settings)

    # Apply overrides
    override_file = os.path.join(svc_path, 'override.env')
    if os.path.exists(override_file):
        overrides = parse_env_file(override_file)
        for key in ['PORT', 'TLS', 'MAX_CONNECTIONS']:
            if key in overrides:
                settings[key] = overrides[key]

    return settings

