def find_effective_value(settings, key):
    """Find effective value considering override keys and nested config keys."""
    # Direct override key takes precedence
    if key in settings:
        return settings[key]

    # Look for nested equivalents
    if key == 'PORT':
        candidates = ['LISTEN_PORT', 'SERVER_PORT']
    elif key == 'TLS':
        candidates = ['TLS_ENABLED', 'SERVER_TLS']
    elif key == 'MAX_CONNECTIONS':
        candidates = ['LIMITS_MAX_CONNECTIONS']
    else:
        candidates = []

    for cand in candidates:
        if cand in settings:
            return settings[cand]

    return None

