def migrate_config(data):
    new_data = {}
    for key, value in data.items():
        if key == "version":
            new_data["version"] = 2
        elif key == "timeoutMs":
            new_data["timeout_s"] = value / 1000.0
        elif key == "retry":
            new_data["retry"] = {
                "attempts": value["count"],
                "backoff_s": value["backoffMs"] / 1000.0,
            }
        elif key == "owners":
            if isinstance(value, str):
                emails = [e.strip().lower() for e in value.split(",")]
                emails = [e for e in emails if e]
                new_data["owners"] = emails
            else:
                # already an array? keep as is per "every other key kept"
                new_data["owners"] = value
        else:
            new_data[key] = value
    # Ensure retry exists if missing
    if "retry" not in new_data:
        new_data["retry"] = { "attempts": 0, "backoff_s": 0 }
    return new_data

